using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
namespace ScoreModern {public sealed partial class Editor {
 void StartTypeListing(string name){if(String.IsNullOrWhiteSpace(name))throw new InvalidDataException("Enter a text filename.");string path=Path.GetFullPath(name);if(!File.Exists(path))throw new FileNotFoundException("Text file not found.",path);string contents=Encoding.GetEncoding(437).GetString(File.ReadAllBytes(path));string[] lines=contents.Replace("\r\n","\n").Replace('\r','\n').Split('\n');if(lines.Length>0&&lines[lines.Length-1].Length==0)lines=lines.Take(lines.Length-1).ToArray();if(ListDialogs){ShowCopyableList(Path.GetFileName(path),"command-list",String.Join("\r\n",lines));return;}letterHelpPages=new List<string[]>();for(int i=0;i<lines.Length;i+=19)letterHelpPages.Add(lines.Skip(i).Take(19).ToArray());if(letterHelpPages.Count==0)letterHelpPages.Add(new string[0]);var last=letterHelpPages[letterHelpPages.Count-1].ToList();last.Add("Press any key to continue.");letterHelpPages[letterHelpPages.Count-1]=last.ToArray();letterHelpIsType=true;letterHelpPreviousMessage="";letterHelpPage=0;letterHelpTopicPending=false;ShowLetterHelpPage();}
 void AdvanceTypeListing(){if(++letterHelpPage>=letterHelpPages.Count){HideLetterHelp();Message("");command.Clear();return;}ShowLetterHelpPage();}
}}
